   206|    ok: false as const,
   207|    code,
   208|    message: overrides?.message ?? code,
   209|    traceId,
   210|    stage,
   211|    retryable: overrides?.retryable ?? false,
   212|    registrationRequestId: overrides?.registrationRequestId,
   213|    deploymentMarker: DEPLOYMENT_MARKER,
   214|  };
   215|  const status = code === 'EMAIL_EXISTS' ? 409 : code === 'RATE_LIMITED' ? 429 : (code === 'NETWORK_ERROR' || code === 'SERVICE_UNAVAILABLE') ? 503 : 400;
